'use client';

import { useEffect, useState, useRef } from 'react';
import Image from 'next/image';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useSession, signIn, signOut } from 'next-auth/react';
import { getUserId, getDecisions, getUsageCount, isLimitReached, getRemainingUsage, clearData, setOnboardingDone, getOrCreateFingerprint } from '@/services/storage/storage';
import { Decision, Priority, Task } from '@/types';
import { logEvent } from '@/services/analytics/metrics';
import '@/services/analytics/insights';
import { useDecision } from '@/features/decision/useDecision';
import ProfileMenu from '@/components/ProfileMenu';
import ValueHint from '@/components/decision/ValueHint';

const EXAMPLES = [
  'Preciso pagar a fatura do cart├úo que vence hoje, estudar para a prova de amanh├ú e responder os e-mails do trabalho.',
  'Tenho que marcar uma consulta m├®dica, terminar o relat├│rio do projeto para sexta-feira e lavar a lou├ºa.',
  'Renovar o seguro do carro que vence semana que vem, comprar presente de anivers├írio para minha m├úe e fazer supermercado.',
  'Responder mensagens pendentes no WhatsApp, organizar a mesa de trabalho e planejar a viagem de f├®rias.',
  'Pagar o condom├¡nio, agendar a manuten├º├úo do ar condicionado e finalizar a apresenta├º├úo para a diretoria amanh├ú.',
  'Fazer exerc├¡cios por 30 minutos, ler 10 p├íginas de um livro e terminar a funcionalidade nova do app.',
  'Consertar o vazamento da pia, comprar l├ómpadas novas e organizar os documentos do imposto de renda.',
  'Ligar para o banco para contestar uma cobran├ºa, preparar a mala para a viagem e levar o cachorro ao veterin├írio.',
];

export default function Home() {
  const router = useRouter();
  const { data: session, update } = useSession();
  const isPro = session?.user?.plan === 'pro';
  const [userId] = useState<string>(() => typeof window !== 'undefined' ? getUserId() : '');
  const [input, setInput] = useState('');
  const { analyze, loading, result, setResult, error, setError, limitReached, setLimitReached, conversionTrigger, setConversionTrigger } = useDecision(userId);
  const [showUpgradeModal, setShowUpgradeModal] = useState(false);
  const [usageCount, setUsageCount] = useState<number>(() => typeof window !== 'undefined' ? getUsageCount() : 0);
  const [history, setHistory] = useState<Decision[]>([]);
  const [expandedTask, setExpandedTask] = useState<number | null>(null);
  const [copied, setCopied] = useState(false);
  const [shareUrl, setShareUrl] = useState<string | null>(null);
  const [shareCopied, setShareCopied] = useState(false);
  const [shareLoading, setShareLoading] = useState(false);
  const [headerHint, setHeaderHint] = useState("");

  const HEADER_HINTS = [
    "Com continuidade, isso pode evoluir ­ƒöÆ",
    "Essa decis├úo ├® para agora ­ƒöÆ",
    "Com contexto, isso pode melhorar ­ƒöÆ",
  ];

  const [mounted, setMounted] = useState(false);
  const [exampleIndex, setExampleIndex] = useState(-1);
  const [isViewingHistory, setIsViewingHistory] = useState(false);
  const [tourStep, setTourStep] = useState<number>(0); // 0 = hidden, 1 = input, 2 = button...
  const [isRefinementMode, setIsRefinementMode] = useState(false);
  const [localPriorities, setLocalPriorities] = useState<Priority[] | null>(null);
  const [localTasks, setLocalTasks] = useState<Task[] | null>(null);
  const [userAdjustedIds, setUserAdjustedIds] = useState<Set<string>>(new Set());
  const [lastMovedTask, setLastMovedTask] = useState<string | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const analyzeBtnRef = useRef<HTMLButtonElement>(null);
  const hamburgerRef = useRef<HTMLDivElement>(null);
  const [hamburgerOpen, setHamburgerOpen] = useState(false);
  const [activeContext, setActiveContext] = useState<string>(() =>
    typeof window !== 'undefined' ? (localStorage.getItem('decido_context') || 'Voc├¬') : 'Voc├¬'
  );
  const [serverRemainingUsage, setServerRemainingUsage] = useState<number | null>(null);
  const [loadingStep, setLoadingStep] = useState(0);

  const LOADING_MESSAGES = [
    "Entendendo o contexto...",
    "Analisando urg├¬ncias...",
    "Priorizando impactos...",
    "Gerando sua pr├│xima a├º├úo...",
  ];

  useEffect(() => {
    let interval: NodeJS.Timeout;
    if (loading) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setLoadingStep(0);
      interval = setInterval(() => {
        setLoadingStep(prev => (prev + 1) % LOADING_MESSAGES.length);
      }, 2000);
    }
    return () => clearInterval(interval);
  }, [loading, LOADING_MESSAGES.length]);

  useEffect(() => {
    const fetchUsage = async () => {
      try {
        const fp = getOrCreateFingerprint();
        const res = await fetch('/api/usage', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ fingerprint: fp }),
        });
        if (res.ok) {
          const data = await res.json();
          setServerRemainingUsage(data.remaining);
        }

        if (session?.user?.email) {
          const histRes = await fetch('/api/history');
          if (histRes.ok) {
            const histData = await histRes.json();
            setHistory(histData);
          }
        } else {
          // Unauthenticated users (guests) do not have history as per Phase 2 constraints
          setHistory([]);
        }
      } catch (_e) {
        console.warn('Failed to fetch data from server');
      }
    };
    if (mounted) fetchUsage();
  }, [mounted, result, userId, session?.user?.email]); // Atualiza no mount e ap├│s cada an├ílise

  const isDecisionFocus = !!result && !isViewingHistory;
  const reachedLimit = mounted && !isPro && (serverRemainingUsage !== null ? serverRemainingUsage === 0 : isLimitReached());

  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setInput(e.target.value);
    setIsViewingHistory(false);
    
    // Auto-resize
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 150)}px`;
    }
  };

  const handleExample = () => {
    let nextIndex = Math.floor(Math.random() * EXAMPLES.length);
    while (nextIndex === exampleIndex) {
      nextIndex = Math.floor(Math.random() * EXAMPLES.length);
    }
    setExampleIndex(nextIndex);
    setInput(EXAMPLES[nextIndex]);
    setResult(null);
    setError(null);
    setIsRefinementMode(false);
    setIsViewingHistory(false);
    logEvent('example_used', userId);

    // Auto-resize, focus and place cursor at end after render
    setTimeout(() => {
      if (textareaRef.current) {
        textareaRef.current.style.height = 'auto';
        textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 150)}px`;
        textareaRef.current.focus();
        const len = textareaRef.current.value.length;
        textareaRef.current.setSelectionRange(len, len);
      }
    }, 0);
  };

  const handleShareCopy = async () => {
    if (!result || shareLoading) return;
    setShareLoading(true);
    try {
      let url = shareUrl;
      if (!url) {
        const res = await fetch('/api/share', {

          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(result),
        });
        const data = await res.json();
        url = data.share_url;
        setShareUrl(url);
      }
      await navigator.clipboard.writeText(window.location.origin + url);
      setShareCopied(true);
      logEvent('share_link_copied', userId);
      setTimeout(() => setShareCopied(false), 2000);
    } catch {
      // silent fail
    } finally {
      setShareLoading(false);
    }
  };

  const handleCopy = async () => {
    if (!result) return;
    try {
      await navigator.clipboard.writeText(result.primary_action || result.recommended_action || '');
      setCopied(true);
      logEvent('copy_action', userId);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // fallback: do nothing silently
    }
  };

  useEffect(() => {
    if (tourStep === 4) {
      document.getElementById('app-footer')?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [tourStep]);

  const handleClearData = async () => {
    if (window.confirm('Tem certeza que deseja apagar todo o hist├│rico de decis├Áes?')) {
      clearData();
      if (session?.user) {
        try {
          await fetch('/api/history', { method: 'DELETE' });
        } catch (e) {
          console.error('Failed to delete history on server', e);
        }
      }
      setHistory([]);
      setResult(null);
      setInput('');
      setIsViewingHistory(false);
      setExampleIndex(-1);
      logEvent('clear_data', userId);
    }
  };

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setMounted(true);
    const syncUsage = async () => {
      try {
        const fp = getOrCreateFingerprint();
        const res = await fetch(`/api/usage/sync?fingerprint=${fp}`);
        const data = await res.json();
        setUsageCount(data.count);
        localStorage.setItem('decido_usage_count', String(data.count));
      } catch (_e) {
        // silent fail, fallback to LS
      }
    };

    update();
    syncUsage();
    logEvent('page_view', userId, { usage: usageCount });
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setLocalPriorities(null);
    setLocalTasks(null);
    setUserAdjustedIds(new Set());
    setShareUrl(null);
    setShareCopied(false);
    setExpandedTask(null);
  }, [result]);

  useEffect(() => {
    if (!hamburgerOpen) return;
    const handleClick = (e: MouseEvent) => {
      if (hamburgerRef.current && !hamburgerRef.current.contains(e.target as Node)) {
        setHamburgerOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, [hamburgerOpen]);

  const handleAnalyze = () => {
    analyze(input, isRefinementMode, isPro, () => {
      setHeaderHint(HEADER_HINTS[Math.floor(Math.random() * HEADER_HINTS.length)]);
      setHistory(getDecisions());
      setUsageCount(getUsageCount());
      setIsViewingHistory(true);
      setIsRefinementMode(false);
      setTimeout(() => {
        const resultSection = document.querySelector('.result-section') as HTMLElement;
        if (resultSection) {
          const yOffset = -60;
          const y = resultSection.getBoundingClientRect().top + window.pageYOffset + yOffset;
          window.scrollTo({ top: y, behavior: 'smooth' });
        }
      }, 100);
    });
  };

  const PRIORITY_LEVELS: Priority['level'][] = ['alta', 'm├®dia', 'baixa'];
  const TASK_LEVELS: Task['priority'][] = ['high', 'medium', 'low'];

  const movePriority = (globalIndex: number, direction: 'up' | 'down') => {
    const source = localPriorities ?? result!.priorities;
    const item = source[globalIndex];
    const idx = PRIORITY_LEVELS.indexOf(item.level);
    const newIdx = direction === 'up' ? idx - 1 : idx + 1;
    if (newIdx < 0 || newIdx >= PRIORITY_LEVELS.length) return;
    setLocalPriorities(source.map((p, i) => i === globalIndex ? { ...p, level: PRIORITY_LEVELS[newIdx] } : p));
    setUserAdjustedIds(prev => new Set([...prev, item.task]));
    setLastMovedTask(item.task);
    setTimeout(() => setLastMovedTask(null), 200);
  };

  const moveTask = (globalIndex: number, direction: 'up' | 'down') => {
    const source = localTasks ?? result!.tasks!;
    const item = source[globalIndex];
    const idx = TASK_LEVELS.indexOf(item.priority);
    const newIdx = direction === 'up' ? idx - 1 : idx + 1;
    if (newIdx < 0 || newIdx >= TASK_LEVELS.length) return;
    setLocalTasks(source.map((t, i) => i === globalIndex ? { ...t, priority: TASK_LEVELS[newIdx] } : t));
    setUserAdjustedIds(prev => new Set([...prev, item.name]));
    setLastMovedTask(item.name);
    setTimeout(() => setLastMovedTask(null), 200);
  };

  const handleLoadHistory = (decision: Decision) => {
    logEvent('history_opened', userId, { decisionId: decision.id });
    setInput(decision.input);
    setResult(decision.output);
    setIsViewingHistory(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
    
    // Auto-resize after render
    setTimeout(() => {
      if (textareaRef.current) {
        textareaRef.current.style.height = 'auto';
        textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 150)}px`;
      }
    }, 0);
  };

  const formatRelativeDate = (timestamp: number): string => {
    // eslint-disable-next-line react-hooks/purity
    const diff = Date.now() - timestamp;
    const minutes = Math.floor(diff / 60000);
    if (minutes < 1) return 'agora mesmo';
    if (minutes < 60) return `h├í ${minutes} min`;
    const hours = Math.floor(minutes / 60);
    if (hours < 24) return `h├í ${hours}h`;
    const days = Math.floor(hours / 24);
    return `h├í ${days} dia${days > 1 ? 's' : ''}`;
  };

  const formatAbsoluteDate = (timestamp: number): string => {
    return new Intl.DateTimeFormat('pt-BR', {
      day: '2-digit',
      month: '2-digit',
      year: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
    }).format(new Date(timestamp));
  };

  const renderTourPopover = (step: number) => (
    <div className={`tour-popover tour-popover--step-${step}`}>
      <div className="tour-content">
        {step === 1 ? (
          <>
            <h3>Entrada de Dados</h3>
            <p>Cole sua lista de tarefas ou descreva uma situa├º├úo. Seja espec├¡fico sobre prazos para melhores resultados.</p>
          </>
        ) : step === 2 ? (
          <>
            <h3>An├ílise Inteligente</h3>
            <p>O Decido organiza tudo por prioridade e sugere a melhor a├º├úo imediata.</p>
          </>
        ) : step === 3 ? (
          <>
            <h3>Hist├│rico Local</h3>
            <p>Suas decis├Áes passadas ficam salvas apenas no seu navegador para consulta r├ípida.</p>
          </>
        ) : (
          <>
            <h3>Limite e Privacidade</h3>
            <p>Acompanhe seu limite de uso e limpe seus dados quando quiser para reiniciar o hist├│rico.</p>
          </>
        )}
      </div>
      <div className="tour-footer">
        <button className="tour-btn-secondary" onClick={() => { setOnboardingDone(); setTourStep(0); }}>Pular</button>
        <div className="tour-btn-group">
          {step < 4 ? (
            <button className="tour-btn-primary" onClick={() => setTourStep(step + 1)}>Pr├│ximo</button>
          ) : (
            <button className="tour-btn-primary" onClick={() => { setOnboardingDone(); setTourStep(0); }}>Entendi</button>
          )}
        </div>
      </div>
      <div className="tour-arrow"></div>
    </div>
  );

  return (
    <main>
      <header style={{ width: '100%', maxWidth: '1400px', margin: '0 auto', padding: '1.5rem 2rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <Link href="/" className="logo-container" style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', cursor: 'pointer', transition: 'opacity 0.2s' }}>
            <Image 
              src="/images/app-icon.png" 
              alt="Decido Logo" 
              width={52}
              height={52}
              style={{ borderRadius: '12px', objectFit: 'cover' }} 
            />
          </Link>
          
          {mounted && (
            <div className="quick-actions">

              {/* Desktop: icon buttons */}
              <div className="quick-actions-desktop">
                <ProfileMenu
                  activeContext={activeContext}
                  onContextChange={(label) => {
                    setActiveContext(label);
                    localStorage.setItem('decido_context', label);
                  }}
                />
                <Link href="/" className="quick-action-btn" title="Ir para Home" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m3 9 9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><polyline points="9 22 9 12 15 12 15 22"/></svg>
                </Link>
                {(history.length > 0 || result) && (
                  <button
                    className="quick-action-btn"
                    title="Nova An├ílise"
                    onClick={() => {
                      setResult(null);
                      setInput('');
                      setIsViewingHistory(false);
                      setExampleIndex(-1);
                      window.scrollTo({ top: 0, behavior: 'smooth' });
                      if (textareaRef.current) textareaRef.current.style.height = 'auto';
                    }}
                  >
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
                  </button>
                )}
              </div>

              {/* Mobile: hamburger */}
              <div className="quick-actions-mobile" ref={hamburgerRef}>
                <button
                  className="quick-action-btn"
                  aria-label="Menu"
                  onClick={() => setHamburgerOpen(o => !o)}
                >
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="18" x2="21" y2="18"/></svg>
                </button>
                {hamburgerOpen && (
                  <div className="context-switcher-menu hamburger-menu">
                    {([
                      { label: 'Voc├¬ > pessoal', main: 'Voc├¬', sub: 'pessoal' },
                      { label: 'Time > workspace', main: 'Time', sub: 'workspace' },
                    ]).map(({ label, main, sub }) => (
                      <button
                        key={label}
                        className={`context-switcher-item${activeContext === label ? ' context-switcher-item--active' : ''}`}
                        onClick={() => {
                          setActiveContext(label);
                          localStorage.setItem('decido_context', label);
                          setHamburgerOpen(false);
                        }}
                      >
                        {main} <span style={{ opacity: 0.45 }}>{`- ${sub}`}</span>
                      </button>
                    ))}
                    <div className="context-switcher-divider" />
                    <Link
                      href="/"
                      className="context-switcher-item"
                      style={{ display: 'block', textDecoration: 'none' }}
                      onClick={() => setHamburgerOpen(false)}
                    >
                      Ir para Home
                    </Link>
                    {(history.length > 0 || result) && (
                      <button
                        className="context-switcher-item"
                        onClick={() => {
                          setResult(null);
                          setInput('');
                          setIsViewingHistory(false);
                          setExampleIndex(-1);
                          window.scrollTo({ top: 0, behavior: 'smooth' });
                          if (textareaRef.current) textareaRef.current.style.height = 'auto';
                          setHamburgerOpen(false);
                        }}
                      >
                        Nova an├ílise
                      </button>
                    )}
                    <div className="context-switcher-divider" />
                    {session ? (
                      <>
                        <Link
                          href="/minha-conta"
                          className="context-switcher-item"
                          style={{ display: 'block', textDecoration: 'none' }}
                          onClick={() => setHamburgerOpen(false)}
                        >
                          Minha conta
                        </Link>
                        <button
                          className="context-switcher-item context-switcher-item--muted"
                          onClick={() => { signOut(); setHamburgerOpen(false); }}
                        >
                          Sair
                        </button>
                      </>
                    ) : (
                      <button
                        className="context-switcher-item"
                        onClick={() => { signIn('google'); setHamburgerOpen(false); }}
                      >
                        Entrar
                      </button>
                    )}
                  </div>
                )}
              </div>

            </div>
          )}
        </header>
    <div className={`container ${isDecisionFocus ? 'decision-focus-dim' : ''}`} key={mounted ? 'client' : 'server'}>

        <header className="header">
          <h1>Decido</h1>
          <p>Seu assistente inteligente de decis├Áes</p>
        </header>

        <>
            <section className={`input-section ${(tourStep === 1 || tourStep === 2) ? 'tour-highlight-container' : ''}`} style={{ position: 'relative' }}>
              <textarea
                ref={textareaRef}
                id="task-input"
                rows={2}
                className={`auto-resize-textarea ${tourStep === 1 ? 'tour-highlight' : ''}`}
                placeholder="O que est├í disputando sua aten├º├úo agora?"
                value={input}
                onChange={handleInputChange}
                disabled={loading}
              />
              {tourStep === 1 && renderTourPopover(1)}
              {(!input || EXAMPLES.includes(input)) && (
                <div className="example-block">
                  <button
                    id="try-example-btn"
                    className="example-btn"
                    onClick={handleExample}
                    disabled={loading}
                  >
                    {exampleIndex === -1 ? 'Ô£¿ Tentar com um exemplo' : 'Ô£¿ Tentar outro exemplo'}
                  </button>
                </div>
              )}

              <div className={tourStep === 2 ? 'tour-highlight-container' : ''} style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem', width: '100%', position: 'relative' }}>
                {isRefinementMode && (
                  <span className="refinement-indicator">Refinando an├ílise anterior</span>
                )}
                <button
                  ref={analyzeBtnRef}
                  id="analyze-btn"
                  className={tourStep === 2 ? 'tour-highlight' : ''}
                  onClick={handleAnalyze}
                  disabled={loading || !input || input.trim().length === 0}
                >
                  {loading ? (
                    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.75rem' }}>
                      <div className="spinner-tiny" style={{ width: '16px', height: '16px', border: '2px solid rgba(255,255,255,0.3)', borderTopColor: 'white', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }}></div>
                      <span style={{ minWidth: '180px', textAlign: 'left' }}>{LOADING_MESSAGES[loadingStep]}</span>
                    </div>
                  ) : (result ? 'Rever decis├úo' : 'Analisar')}
                </button>
                {tourStep === 2 && renderTourPopover(2)}
              </div>
            </section>

            {reachedLimit && (
              <div className="error-message">
                {session ? 'Suas decis├Áes de hoje chegaram ao limite.' : 'Limite de convidado atingido.'}{' '}
                <button
                  className="limit-link"
                  onClick={() => {
                    setLimitReached({
                      title: session ? "Sua clareza di├íria est├í pausada." : "Voc├¬ atingiu o limite de convidado.",
                      description: session 
                        ? "Voc├¬ chegou ao limite de an├ílises gratuitas. No PRO, o Decido j├í sabe ÔÇö e te diz o que fazer sem repetir o esfor├ºo."
                        : "Para continuar decidindo hoje e salvar seu hist├│rico com seguran├ºa, crie sua conta gratuita.",
                      cta: session ? "Continuar agora com PRO" : "Criar conta gratuita",
                      link: session ? "/limite" : "/auth/signup",
                      secondary_cta: session ? null : "Ver planos PRO",
                      secondary_link: session ? null : "/limite"
                    });
                    setShowUpgradeModal(true);
                  }}
