import NextAuth from 'next-auth';
import Google from 'next-auth/providers/google';
import Credentials from 'next-auth/providers/credentials';
import { getOrCreateUser, getUserByEmail } from '@/lib/users-db';
import bcrypt from 'bcryptjs';

export const { handlers, auth, signIn, signOut } = NextAuth({
  providers: [
    Google({
      clientId: process.env.GOOGLE_CLIENT_ID,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET,
    }),
    Credentials({
      name: 'Credentials',
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Senha", type: "password" }
      },
      async authorize(credentials) {
        if (!credentials?.email || !credentials?.password) return null;
        
        const user = getUserByEmail(credentials.email as string);
        if (!user || !user.password) return null;

        const isValid = await bcrypt.compare(credentials.password as string, user.password);
        if (!isValid) return null;

        return {
          id: String(user.id),
          email: user.email,
          name: user.name,
          plan: user.plan,
          role: user.role
        };
      }
    })
  ],
  trustHost: true,
  debug: true,
  session: {
    strategy: 'jwt',
    maxAge: 30 * 24 * 60 * 60, // 30 days
  },
  pages: {
    signIn: '/auth/signin',
  },
  callbacks: {
    async jwt({ token, user }: { token: unknown; user: unknown }) {
      if (user) {
        (token as any).id = (user as any).id;
        (token as any).plan = (user as any).plan || 'free';
        (token as any).role = (user as any).role;
      }
      
      const email = (token as any).email as string | undefined;
      if (email && !(token as any).plan) {
        const userRow = getOrCreateUser(
          email, 
          (token as any).name as string || undefined, 
          (token as any).picture as string || undefined
        );
        (token as any).plan = userRow.plan;
        (token as any).role = userRow.role;
        (token as any).id = String(userRow.id);
      }
      return token;
    },
    async session({ session, token }: { session: unknown; token: unknown }) {
      if ((session as any).user) {
        (session as any).user.id = (token as any).id;
        (session as any).user.plan = (token as any).plan;
        (session as any).user.role = (token as any).role;
      }
      return session;
    },
  },
});

